{
  "headline": "FDA's records trace our supply to a plant classified OAI 714 days after the shortage posting and subject to import alerts and warning letters",
  "headline_cites": ["D9", "D10", "E20", "E19", "E31"],
  "sentences": [
    {
      "text": "FDA first posted the azacitidine shortage on 2020-12-18 and it remains current as of 2026-10-21, spanning 70 months.",
      "cites": ["E43", "D14"]
    },
    {
      "text": "A registered plant for Accord Healthcare's product, Intas Pharmaceuticals Limited (FEI 3004011473), received an OAI classification on 2022-12-02, 714 days after the shortage posting.",
      "cites": ["D9", "E22", "E18"]
    },
    {
      "text": "FDA issued an import alert (66-40) for Intas Pharmaceuticals Limited on 2023-06-01 and again on 2023-11-14, and warning letters on 2023-07-28 and 2023-11-21 for two Intas sites.",
      "cites": ["E20", "E21", "E19", "E31"]
    },
    {
      "text": "Multiple earlier inspections of Intas sites were classified VAI between 2019 and 2022, with classification letters issued 294 to 570 days before the shortage posting.",
      "cites": ["D4", "D5", "D6", "D7", "E15", "E16", "E30"]
    },
    {
      "text": "An alternate manufacturer option ranked by rule is BluePoint Laboratories, which is not on FDA's shortage list today and uses Sindan-Pharma Srl (last inspection NAI 2024-08-02).",
      "cites": ["D11"]
    },
    {
      "text": "P&T-approved interchange options include Hikma Pharmaceuticals USA Inc. (approved 2026-04-04) and Accord Healthcare Inc. (approved 2025-09-24) as same-product alternates.",
      "cites": ["D12", "D13"]
    }
  ]
}
